import "server-only";
import { mkdir, readFile, writeFile, rm } from "node:fs/promises";
import path from "node:path";
import { randomUUID } from "node:crypto";
import { get, del, list } from "@vercel/blob";
import { db } from "@/lib/db";
import type { Prisma } from "@/generated/prisma/client";
import { MAX_PDF_BYTES, validatePdf } from "@/lib/validation";
import { AppError } from "@/lib/errors";

export function hasBlobStorage() {
  return Boolean(
    process.env.BLOB_READ_WRITE_TOKEN ||
    (process.env.BLOB_STORE_ID && process.env.NODE_ENV === "production"),
  );
}

export function validStoragePath(userId: string, pathname: string) {
  return new RegExp(`^resumes/${userId}/[a-f0-9-]{36}\\.pdf$`).test(pathname);
}
export function safeFileName(value: string) {
  return (
    value.replace(/[\r\n\\/\x00-\x1f]/g, "_").slice(0, 150) || "resume.pdf"
  );
}
export async function readAttachment(userId: string, storagePath: string) {
  if (!validStoragePath(userId, storagePath))
    throw new AppError("Invalid attachment location.");
  if (!hasBlobStorage() && process.env.NODE_ENV !== "production") {
    try {
      return await readFile(path.join(process.cwd(), "uploads", storagePath));
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT")
        throw new AppError(
          "PDF could not be loaded. Upload it again in Settings.",
        );
      throw error;
    }
  }
  const abortSignal = AbortSignal.timeout(30000);
  const blob = await get(storagePath, {
    access: "private",
    useCache: false,
    abortSignal,
  });
  if (!blob || blob.statusCode !== 200)
    throw new AppError("PDF could not be loaded. Upload it again in Settings.");
  const reader = blob.stream.getReader();
  abortSignal.addEventListener(
    "abort",
    () => {
      void reader.cancel().catch(() => {});
    },
    { once: true },
  );
  const chunks: Uint8Array[] = [];
  let size = 0;
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      size += value.length;
      if (size > MAX_PDF_BYTES) {
        await reader.cancel();
        throw new AppError("PDF exceeds 5 MB.");
      }
      abortSignal.throwIfAborted();
      chunks.push(value);
    }
  } finally {
    reader.releaseLock();
  }
  abortSignal.throwIfAborted();
  return Buffer.concat(chunks);
}
export async function activateResume(
  userId: string,
  storagePath: string,
  fileName: string,
) {
  try {
    const bytes = await readAttachment(userId, storagePath);
    validatePdf(bytes, "application/pdf");
    await db.$transaction(async (tx) => {
      await tx.$queryRaw`SELECT id FROM "User" WHERE id = ${userId} FOR UPDATE`;
      const user = await tx.user.findUnique({ where: { id: userId } });
      if (!user || user.deletionRequestedAt || user.isSuspended)
        throw new AppError("Account unavailable.");
      const existing = await tx.attachment.findFirst({
        where: { userId, storagePath },
      });
      if (existing?.deletedAt)
        throw new AppError("This PDF was removed. Upload it again.");
      const attachment =
        existing ??
        (await tx.attachment.create({
          data: { userId, storagePath, fileName: safeFileName(fileName) },
        }));
      await tx.user.update({
        where: { id: userId },
        data: { currentAttachmentId: attachment.id },
      });
    });
  } catch (error) {
    await discardUnactivatedResume(userId, storagePath);
    throw error;
  }
  await cleanupAttachments(userId);
}
// Retire the path under the same owner lock as activation. The tombstone closes
// the gap between a storage delete and a concurrent unsuspension/activation.
export async function discardUnactivatedResume(
  userId: string,
  storagePath: string,
  unavailableSince?: Date,
) {
  if (!validStoragePath(userId, storagePath))
    throw new AppError("Invalid attachment location.");
  const candidate = await db.$transaction(async (tx) => {
    await tx.$queryRaw`SELECT id FROM "User" WHERE id = ${userId} FOR UPDATE`;
    const user = await tx.user.findUnique({
      where: { id: userId },
      select: { isSuspended: true, deletionRequestedAt: true },
    });
    if (!user) return { id: null };
    if (
      unavailableSince &&
      !user.isSuspended &&
      !(
        user.deletionRequestedAt && user.deletionRequestedAt <= unavailableSince
      )
    )
      return null;
    const existing = await tx.attachment.findFirst({
      where: { userId, storagePath },
      select: { id: true, rejectedAt: true },
    });
    if (existing) return existing.rejectedAt ? { id: existing.id } : null;
    // Deletion is irreversible; no tombstone is needed to block activation.
    if (user.deletionRequestedAt) return { id: null };
    return tx.attachment.create({
      data: {
        userId,
        storagePath,
        fileName: "resume.pdf",
        deletedAt: new Date(),
        rejectedAt: new Date(),
      },
      select: { id: true },
    });
  });
  if (!candidate) return;
  await deleteStoragePath(userId, storagePath);
  if (candidate.id)
    await db.attachment.updateMany({
      where: { id: candidate.id, userId, rejectedAt: { not: null } },
      data: { storageDeletedAt: new Date() },
    });
}
async function deleteStoragePath(userId: string, storagePath: string) {
  if (!validStoragePath(userId, storagePath))
    throw new AppError("Invalid attachment location.");
  if (hasBlobStorage())
    await del(storagePath, { abortSignal: AbortSignal.timeout(15000) });
  else if (process.env.NODE_ENV !== "production")
    await rm(path.join(process.cwd(), "uploads", storagePath), { force: true });
}
export async function storeLocalResume(userId: string, file: File) {
  if (process.env.NODE_ENV === "production" || hasBlobStorage())
    throw new AppError("Use the secure Blob upload.");
  if (file.size > MAX_PDF_BYTES) throw new AppError("Choose a PDF up to 5 MB.");
  const bytes = Buffer.from(await file.arrayBuffer());
  validatePdf(bytes, file.type);
  const storagePath = `resumes/${userId}/${randomUUID()}.pdf`;
  const full = path.join(process.cwd(), "uploads", storagePath);
  await mkdir(path.dirname(full), { recursive: true, mode: 0o700 });
  await writeFile(full, bytes, { mode: 0o600 });
  await activateResume(userId, storagePath, file.name);
}
function cleanupAttachmentWhere(
  userId: string,
  currentAttachmentId: string | null | undefined,
): Prisma.AttachmentWhereInput {
  return {
    userId,
    storageDeletedAt: null,
    ...(currentAttachmentId ? { id: { not: currentAttachmentId } } : {}),
    campaigns: {
      none: {
        userId,
        sends: {
          some: {
            OR: [
              { status: "QUEUED" },
              { deliveryState: { in: ["ATTEMPTING", "UNCERTAIN"] } },
            ],
          },
        },
      },
    },
  };
}

export async function hasPendingAttachmentCleanup(
  userId: string,
  currentAttachmentId: string | null,
) {
  return Boolean(
    await db.attachment.findFirst({
      where: cleanupAttachmentWhere(userId, currentAttachmentId),
      select: { id: true },
    }),
  );
}

export async function cleanupAttachments(userId: string) {
  const old = await db.$transaction(async (tx) => {
    await tx.$queryRaw`SELECT id FROM "User" WHERE id = ${userId} FOR UPDATE`;
    const user = await tx.user.findUnique({
      where: { id: userId },
      select: { currentAttachmentId: true },
    });
    const candidates = await tx.attachment.findMany({
      where: cleanupAttachmentWhere(userId, user?.currentAttachmentId),
      orderBy: [{ createdAt: "asc" }, { id: "asc" }],
      take: 10,
    });
    await tx.attachment.updateMany({
      where: {
        userId,
        id: { in: candidates.map((f) => f.id) },
        deletedAt: null,
      },
      data: { deletedAt: new Date() },
    });
    return candidates;
  });
  const files = old.filter((file) =>
    validStoragePath(userId, file.storagePath),
  );
  if (!files.length) return;
  try {
    if (hasBlobStorage())
      await del(
        files.map((file) => file.storagePath),
        {
          abortSignal: AbortSignal.timeout(15000),
        },
      );
    else if (process.env.NODE_ENV !== "production")
      await Promise.all(
        files.map((file) =>
          rm(path.join(process.cwd(), "uploads", file.storagePath), {
            force: true,
          }),
        ),
      );
    else return;
    // Preserve historical rows, but never repeat completed physical deletions.
    await db.attachment.updateMany({
      where: {
        userId,
        id: { in: files.map((file) => file.id) },
        storageDeletedAt: null,
      },
      data: { storageDeletedAt: new Date() },
    });
  } catch {
    /* Unfinished storage work remains pending for the next cleanup job. */
  }
}

export async function deleteOwnedResumes(userId: string) {
  // UUID IDs are used as exact tenant prefixes; never accept arbitrary path input.
  if (!/^[a-f0-9-]{36}$/.test(userId)) throw new AppError("Invalid account.");
  if (hasBlobStorage()) {
    let cursor: string | undefined;
    do {
      const page = await list({
        prefix: `resumes/${userId}/`,
        limit: 100,
        cursor,
        abortSignal: AbortSignal.timeout(15000),
      });
      if (page.blobs.length)
        await del(
          page.blobs.map((blob) => blob.url),
          { abortSignal: AbortSignal.timeout(15000) },
        );
      cursor = page.hasMore ? page.cursor : undefined;
    } while (cursor);
  } else if (process.env.NODE_ENV === "production") {
    throw new AppError("Private Blob storage is not configured.");
  }
  await rm(path.join(process.cwd(), "uploads", "resumes", userId), {
    recursive: true,
    force: true,
  });
}
